:root { --max-width: 1100px; }
main {
  max-width: var(--content-width, var(--max-width));
  margin: 0 auto;
}

main { max-width: 860px; margin: 0 auto; }
.full-bleed {
  /* Break out of main's max-width by reaching back through the
     grid column. Works because main is centred inside a larger
     grid cell; negative margin pulls the bleed item back to the
     cell edge. */
  margin-inline: calc((var(--column-width) - var(--prose-width)) / -2);
  max-width: none;
}
